    static_assert(LEN_ARRAY(dmx_animation_table) == DMX_ANIM_COUNT);

    config_animation_entry_t get_config_animation_name_dmx(size_t index) {
        assert(index < DMX_ANIM_COUNT);
        const auto& entry = dmx_animation_table[index];
        return { DMX_STRINGS + entry.name, DMX_STRINGS + entry.id, DMX_STRINGS + entry.fqid, DMX_STRINGS + entry.fqname, entry.anim_index, entry.set, entry.layout };
    }

    int config_parse_animation_name_dmx(config::config_t& config, const char *value) {
        int ret = -1;
        for (size_t i = 0;ret < 0 && i < DMX_ANIM_COUNT;++i) {
            const auto& entry = dmx_animation_table[i];
            if (strcmp(value, DMX_STRINGS + entry.name) == 0 ||
                strcmp(value, DMX_STRINGS + entry.id) == 0 ||
                strcmp(value, DMX_STRINGS + entry.fqid) == 0 ||
                strcmp(value, DMX_STRINGS + entry.fqname) == 0) {
                config.animation_index = entry.anim_index;
                config.animation_dm_set = entry.set;
                config.animation_sprite_sheet_layout = entry.layout;
                ret = entry.anim_index;
                break;
            }
        }
        return ret;
    }
